occ={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,x in enumerate(row) if x}
# candidates 2x2 and L shapes
pieces=[]
for r in range(6):
 for c in range(6):
  cells={(r+i,c+j) for i in range(2) for j in range(2)}
  if cells<=occ: pieces.append(('square',cells))
  for miss in [(0,0),(0,1),(1,0),(1,1)]:
   cells={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+miss[0],c+miss[1])}
   if cells<=occ: pieces.append((f'L missing {miss}',cells))
def covers(remaining, chosen=[]):
 if not remaining: return [chosen]
 first=min(remaining)
 res=[]
 for typ,cells in pieces:
  if first in cells and cells<=remaining:
   res += covers(remaining-cells, chosen+[(typ,cells)])
 return res
sol=covers(occ)
len(sol), [[(t,len(c)) for t,c in s] for s in sol[:10]]
